-- =============================================================================
-- 185_seed_medicine_catalog_syt.sql
-- Nap DANH MUC THUOC THAT (thuoc trung thau So Y te, QD 317/QD-SYT,
-- hieu luc 2025-07-15 .. 2027-08-26) thay cho 30 dong seed demo.
--
-- Nguon: bo du lieu cong khai danghauyd2011-pharm/DMT (docs/data_0..3.json).
-- 1552 dong goc -> 1508 dong sau khi gop trung
-- (trung = cung ten thuoc + hoat chat + nong do + SDK + don vi tinh).
--
-- Mang theo: hoat chat, nong do/ham luong, dang bao che, duong dung, quy cach,
-- so dang ky, hang + nuoc san xuat, nha thau, don gia trung thau, so thu tu TT20,
-- va co kiem soat dac biet (gay nghien / huong than / tien chat) suy tu MaPhanLoai.
--
-- Idempotent: chi INSERT dong co MedicineCode chua ton tai; chay lai khong nhan doi.
-- KHONG dung toi 30 dong seed cu (PARA500, TH_*, DL00x) -> KB tuong tac thuoc
-- (138/166_*) va cac don thuoc da tao van tro dung.
-- =============================================================================

SET NOCOUNT ON;

-- ── 1. Noi rong cot cho du lieu that ────────────────────────────────────────
-- Danh muc that co hoat chat phoi hop (toi 788 ky tu), nong do da thanh phan
-- (toi 1038) va quy cach dong goi dai (toi 157). Giu nguyen kich thuoc cu thi
-- phai cat cut -> mat thong tin lam sang. Chi NOI RONG, khong thu hep.
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='ActiveIngredient' AND CHARACTER_MAXIMUM_LENGTH < 1000)
    ALTER TABLE Medicines ALTER COLUMN ActiveIngredient nvarchar(1000) NULL;
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='Concentration' AND CHARACTER_MAXIMUM_LENGTH < 1000)
    ALTER TABLE Medicines ALTER COLUMN Concentration nvarchar(1000) NULL;
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='PackageUnit' AND CHARACTER_MAXIMUM_LENGTH < 200)
    ALTER TABLE Medicines ALTER COLUMN PackageUnit nvarchar(200) NULL;
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='RegistrationNumber' AND CHARACTER_MAXIMUM_LENGTH < 200)
    ALTER TABLE Medicines ALTER COLUMN RegistrationNumber nvarchar(200) NULL;
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='ManufacturerCountry' AND CHARACTER_MAXIMUM_LENGTH < 200)
    ALTER TABLE Medicines ALTER COLUMN ManufacturerCountry nvarchar(200) NULL;
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
           WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='Country' AND CHARACTER_MAXIMUM_LENGTH < 200)
    ALTER TABLE Medicines ALTER COLUMN Country nvarchar(200) NULL;

-- Dang bao che (vd "Dung dich tiem", "Vien nen bao phim") truoc day khong co cho luu.
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
               WHERE TABLE_NAME='Medicines' AND COLUMN_NAME='DosageForm')
    ALTER TABLE Medicines ADD DosageForm nvarchar(200) NULL;
GO

-- ── 2. Bang tam chua danh muc ───────────────────────────────────────────────
IF OBJECT_ID('tempdb..#MedCatalog') IS NOT NULL DROP TABLE #MedCatalog;
-- COLLATE DATABASE_DEFAULT: tempdb mang collation server (SQL_Latin1) con DB HIS la
-- Vietnamese_CI_AS -> khong ep collation thi phep so sanh MedicineCode o buoc 3 no
-- "Cannot resolve the collation conflict".
CREATE TABLE #MedCatalog (
    MedicineCode        nvarchar(50)   COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
    MedicineName        nvarchar(500)  COLLATE DATABASE_DEFAULT NOT NULL,
    MedicineCodeBYT     nvarchar(50)   COLLATE DATABASE_DEFAULT NULL,
    RegistrationNumber  nvarchar(200)  COLLATE DATABASE_DEFAULT NULL,
    ActiveIngredient    nvarchar(1000) COLLATE DATABASE_DEFAULT NULL,
    Concentration       nvarchar(1000) COLLATE DATABASE_DEFAULT NULL,
    DosageForm          nvarchar(200)  COLLATE DATABASE_DEFAULT NULL,
    MedicineType        int            NOT NULL,
    MedicineGroupCode   nvarchar(50)   COLLATE DATABASE_DEFAULT NULL,
    IsNarcotic          bit            NOT NULL,
    IsPsychotropic      bit            NOT NULL,
    IsPrecursor         bit            NOT NULL,
    IsAntibiotic        bit            NOT NULL,
    IsControlled        bit            NOT NULL,
    Unit                nvarchar(50)   COLLATE DATABASE_DEFAULT NULL,
    PackageUnit         nvarchar(200)  COLLATE DATABASE_DEFAULT NULL,
    RouteCode           nvarchar(50)   COLLATE DATABASE_DEFAULT NULL,
    RouteName           nvarchar(100)  COLLATE DATABASE_DEFAULT NULL,
    Manufacturer        nvarchar(500)  COLLATE DATABASE_DEFAULT NULL,
    ManufacturerCountry nvarchar(200)  COLLATE DATABASE_DEFAULT NULL,
    Country             nvarchar(200)  COLLATE DATABASE_DEFAULT NULL,
    Supplier            nvarchar(500)  COLLATE DATABASE_DEFAULT NULL,
    UnitPrice           decimal(18,2)  NOT NULL
);



-- ── 3. Nap vao Medicines (chi dong chua co) ─────────────────────────────────
    Id, MedicineCode, MedicineName, MedicineCodeBYT, RegistrationNumber,
    ActiveIngredient, Concentration, DosageForm, MedicineType, MedicineGroupCode,
    IsNarcotic, IsPsychotropic, IsPrecursor, IsAntibiotic, IsControlled,
    Unit, PackageUnit, ConversionRate, RouteCode, RouteName,
    Manufacturer, ManufacturerCountry, Country, Supplier,
    UnitPrice, InsurancePrice, ServicePrice,
    IsInsuranceCovered, IsBhytCovered, InsurancePaymentRate,
    IsActive, DisplayOrder, CreatedAt, CreatedBy, IsDeleted
)
SELECT
    NEWID(), c.MedicineCode, c.MedicineName, c.MedicineCodeBYT, c.RegistrationNumber,
    c.ActiveIngredient, c.Concentration, c.DosageForm, c.MedicineType, c.MedicineGroupCode,
    c.IsNarcotic, c.IsPsychotropic, c.IsPrecursor, c.IsAntibiotic, c.IsControlled,
    c.Unit, c.PackageUnit, 1, c.RouteCode, c.RouteName,
    c.Manufacturer, c.ManufacturerCountry, c.Country, c.Supplier,
    c.UnitPrice, c.UnitPrice, c.UnitPrice,
    1, 1, 100,
    1, 0, SYSUTCDATETIME(), NULL, 0
FROM #MedCatalog c
WHERE NOT EXISTS (SELECT 1 FROM Medicines m WHERE m.MedicineCode = c.MedicineCode);

DROP TABLE #MedCatalog;
GO
